NAME = 'vlsJoNT: Het Nieuwe Testament by Nicolaas De Jonge'
BOOK = 'I Peter'

CHAPTERS = {
    1: {
        1: 'Petrus, een apostel van Jezus Christus, aan de uitverkorenen die vreemdelingen zijn der verstrooiing in Pontus, Galatië, Kappadocië, Asië en Bithynië,',
        2: 'naar de voorkennis van God den Vader, in heiligmaking des geestes, tot gehoorzaamheid en besprenging des bloeds van Jezus Christus: genade en vrede zij over ulieden vermenigvuldigd!',
        3: 'Geprezen zij de God en Vader van onzen Heere Jezus Christus, die naar zijn groote barmhartigheid ons heeft wedergeboren tot een levende hope, door de verrijzenis van Jezus Christus: uit de dooden,',
        4: 'tot een onverderfelijk, en onbesmettelijk, en onverwelkelijk erfdeel, dat in de hemelen bewaard wordt voor ulieden,',
        5: 'die in Gods kracht bewaard wordt door het geloof tot een zaligheid die gereed is om geopenbaard te worden in den laatsten tijd;',
        6: 'Waarin gij u verheugt, als het noodig is dat gij nu een weinig bedroefd wordt in velerlei bekoringen,',
        7: 'opdat de beproeving van uw geloof, — die kostbaarder is dan van goud dat vergaat, al is het door vuur beproefd, — bevonden worde tot lof en glorie en eere, in de openbaring van Jezus Christus,',
        8: 'dien gij bemint alhoewel gij Hem niet gezien hebt, in wien gij ook, alhoewel Hem nu niet ziende maar geloovende, u verheugt met een onuitsprekelijke en verheerlijkte vreugde,',
        9: 'verkrijgende het einde uws geloofs, de behoudenis der zielen.',
        10: 'Aangaande welke behoudenis de profeten, die geprofeteerd hebben van de genade jegens ulieden, hebben onderzocht en doorzocht,',
        11: 'doorzoekende welkenen hoedanigen lijd de Geest van Christus die in hen was, bedoelde, die te voren getuigde van de smarten die op Christus zouden komen en de glorie die daarna komen zou;',
        12: 'aan wie geopenbaard is dat zij niet voor zich zelven maar voor ulieden deze dingen bedienden, die nu verkondigd zijn aan ulieden door degenen die u het Evangelie verkondigd hebben in den Heiligen Geest, die gezonden is van den hemel; welke dingen de engelen begeeren in te zien.',
        13: 'Daarom opschortende de lenden uws verstands, zijt nuchter en hoopt volkomen op de genade die u toegebracht wordt in de openbaring van Jezus Christus;',
        14: 'als kinderen der gehoorzaamheid, u niet voegende naar uw vroegere begeerlijkheden uit den tijd uwer onwetendheid,',
        15: 'maar gelijk Hij die u geroepen heeft heilig is, zoo wordt ook gij zelf heilig in geheel uw wandel,',
        16: 'omdat er geschreven is: Zijt heilig, omdat ook Ik heilig ben.',
        17: 'En indien gij als Valer aanroept dengene die, zonder aanzien van personen, oordeelt naar een ieders werk, zoo wandelt dan in vreeze den tijd van uw verblijf op aarde;',
        18: 'wetende dat gij niet door vergankelijke dingen, zilver of goud, losgekocht zijt uit uw ijdelen wandel die u van uw voorouders was overgeleverd,',
        19: 'maar door het kostbare bloed als van een onbevlekt en onberispelijk Lam, Christus;',
        20: 'die wel voorgekend is vóór de grondlegging der wereld, doch aan het einde der tijden geopenbaard is om uwentwil,',
        21: 'die door Hem geloovig zijt in God, die Hem heeft opgewekt uit de dooden en Hem glorie gegeven, zoodat uw geloof ook hoop is op God.',
        22: 'Uw zielen dan gezuiverd hebbende in de gehoorzaamheid der waarheid tot ongeveinsde broederliefde, zoo bemint elkander vuriglijk uit een zuiver hart,',
        23: 'gij die wedergeboren zijt niet uit verderfelijk maar uit onverderfelijk zaad door het woord van God, die leeft en blijft.',
        24: 'Want alle vleesch is als gras, en al zijn glorie als een grasbloem; het gras verdroogt en de bloem valt af;',
        25: 'maar het woord des Heeren blijft tot in eeuwigheid. En dat is het woord dat aan u verkondigd is.',
    },
    2: {
        1: 'Afleggende dan alle kwaadheid, en alle bedrog, en geveinsdheid, en nijdigheid, en alle kwaadsprekendheid,',
        2: 'moet gij, als pasgeboren kinderkens, begeerig zijn naar de geestelijke, onvervalschte melk, opdat gij daardoor moogt opwassen tot behoudenis,',
        3: 'indien gij althans gesmaakt hebt dat de Heere barmhartig is.',
        4: 'Tot wien gij komende, als tot een levenden steen van menschen wel verworpen maar bij God uitverkoren en kostbaar,',
        5: 'zoo wordt gij ook zelf als levende steenen opgebouwd, als een geestelijk huis, om een heilig priesterdom te zijn, om geestelijke offeranden op te dragen die door Jezus Christus aangenaam zijn aan God.',
        6: 'Daarom is er gezegd in de Schriftuur: zie Ik stel in Sion een opperhoeksteen, uitverkoren, kostbaar; en die op Hem vertrouwt zal geenszins beschaamd worden.',
        7: 'Voor ulieden dan die gelooft is de prijs. Maar voor de ongeloovigen is de steen, dien de bouwmeesters weggeworpen hebben, geworden tot een hoofdsteen des hoeks, en een steen des aanstoots en een rots der ergernis,',
        8: 'die zich stooten aan het woord, ongehoorzaam zijnde, waartoe zij ook gesteld zijn.',
        9: 'Maar gijlieden zijt een uitverkoren geslacht, een koninklijk priesterdom, een heilig volk, een volk ten erfdeel, opdat gij de krachten zoudt verkondigen van Hem die u geroepen heeft uit duisternis tot zijn wonderbaar licht.',
        10: 'Gij die eertijds Gods volk niet waart, doch nu Gods volk zijt, die geen barmhartigheid badt verkregen, maar nu barmhartigheid verkregen hebt.',
        11: 'Geliefden, ik vermaan u, als bijwoners en pelgrims, dat gij u onthoudt van de vleeschelijke lusten, die strijd voeren tegen de ziel,',
        12: 'en dat gij uw wandel betamelijk houdt onder de heidenen, opdat zij, in hetgeen zij van u kwaadspreken als van kwaaddoeners, uit de goede werken die zij opmerken, aan God de glorie geven mogen in den dag der bezoeking.',
        13: 'Onderwerpt u aan alle menschelijke ordening, om des Heeren wil, hetzij aan een koning als die de opperste macht heeft,',
        14: 'hetzij aan stadhouders als die gezonden zijn door hem tot straf der kwaaddoeners, doch tot lof dergenen die goed doen.',
        15: 'Want zoo is het de wil van God, dat gij door goed te doen den mond stopt der onwetende en onverstandige menschen.',
        16: 'Als vrije menschen, maar toch de vrijheid niet gebruikende als een dekmantel der kwaadheid, maar als dienaars van God.',
        17: 'Eert allen, bemint de broederschap, vreest God, eert den koning.',
        18: 'Gij dienstknechten, zijt in alle eerbiedigheid onderdanig aan uw meesters, niet alleen aan de goeden en vriendelijken, maar ook aan de verkeerden.',
        19: 'Want dat is Gode aangenaam, als iemand om der konsciëntie wil voor God kwellingen verdraagt, ten onrechte lijdende.',
        20: 'Want wat lof is het als gij verdraagt indien gij zondigt en dan met vuisten geslagen wordt? Maar als gij verdraagt indien gij goed doet en dan lijdt, dat is aangenaam voor God.',
        21: 'Want daartoe zijt gij geroepen, omdat ook Christus voor u geleden heeft, u een voorbeeld nalatende, opdat gij zijn voetstappen zoudt navolgen;',
        22: 'die geen zonde gedaan heeft, en er is geen bedrog in zijn mond gevonden;',
        23: 'die als Hij gescholden werd niet wederschold, en als Hem lijden aangedaan werd niet dreigde, maar Hij gaf zich over aan den rechtvaardigen Rechter;',
        24: 'die zelf onze zonden gedragen heeftin zijn lichaam op het kruis, opdat wij, der zonden afgestorven zijnde, voor de rechtvaardigheid zouden leven, door wiens striemen gij genezen zijt.',
        25: 'Want gij waart als dolende schapen, maar gij zijt nu wedergekeerd tot den Herder en Opziener uwer zielen.',
    },
    3: {
        1: 'Insgelijks gij vrouwen, zijt onderdanig aan uw eigen mannen, opdat ook als sommigen ongehoorzaam zijn aan het woord, zij door de levensmanier der vrouwen zonder woord mogen gewonnen worden,',
        2: 'lettende op uw reinen wandel in eerbiedigheid.',
        3: 'Het versiersel der vrouwen moet niet uitwendig zijn, in gekrulde haren en het omhangen van goud, of het pronken met kleederen,',
        4: 'maar in den verborgen mensch des harten, in het onverderfelijk sieraad van een zachtmoedigen en stillen geest, die kostelijk is voor Gods aangezicht.',
        5: 'Want alzoo ook versierden zich zelven eertijds de heilige vrouwen die op God hoopten, en aan haar mannen onderdanig waren;',
        6: 'zooals ook Sara aan Abraham onderdanig was, hem heer noemende, welker dochteren gij zijt geworden, als gij weldoet en u door geen vreeze laat ontstellen.',
        7: 'Gij mannen evenzoo, leeft met haar verstandig, eerbiedigheid bewijzende aan het vrouwelijk geslacht als aan het zwakste, als die ook mede erfgenamen zijn van de genade des levens, opdat uw gebeden niet worden verhinderd.',
        8: 'En eindelijk, zijt allen eensgezind, medelijdend, broederlievend, barmhartig, nederig,',
        9: 'geen kwaad met kwaad vergeldende of schelden met schelden, maar integendeel hen zegenende, want daartoe zijt gij geroepen, opdat gij den zegen zoudt beërven.',
        10: 'Want die het leven wil beminnen en goede dagen zien, die bedwinge zijn tong van het kwaad en zijn lippen van bedrog te spreken;',
        11: 'die wijke af van het kwaad en doe goed, en zoeke vrede en jage dien na;',
        12: 'want des Heeren oogen zijn op rechtvaardigen en zijn ooren tot hun geroep, maar des Heeren aangezicht is tegen kwaaddoeners.',
        13: 'En wie zal u kwaad doen als gij ijveraars voor het goede geworden zijt?',
        14: 'Maar als gij ook al lijdt om de rechtvaardigheid, dan zijt gij zalig; vreest dan hun dreigementen niet en ontstelt niet,',
        15: 'maar heiligt Christus in uw harten als Heer, altijd gereed tot verdediging aan al wie u rekenschap zou vragen wegens de hope die in u is, maar met zachtmoedigheid en eerbiedigheid,',
        16: 'een goede konsciëntie hebbende, opdat zij beschaamd worden mogen in hetgeen zij van u kwaadspreken, zij die lasteren uw goeden wandel in Christus.',
        17: 'Want beter is het toch, als de wil van God zoo is, om weldoende te lijden, dan kwaaddoende.',
        18: 'Want Christus is ook eenmaal voor de zonden gestorven, de Rechvaardige voor onrechtvaardigen, opdat Hij ons tot God zou brengen; die wel gedood is naar het vleesch, doch levend gemaakt naar den geest,',
        19: 'waarin Hij ook is heengegaan en gepredikt heeft aan geesten in de gevangenis,',
        20: 'die eertijds ongehoorzaam waren toen de lankmoedigheid Gods verlengd was, in de dagen van Noach, terwijl de ark werd toebereid, waarin weinige, dat is acht zielen, behouden werden door het water heen;',
        21: 'dat water, waarvan het tegenbeeld, de doop, u nu ook behoudt, niet als een afwassching van de onreinheid des lichaams, maar als de toezegging van een goede konsciëntie tot God, door de verrijzenis van Jezus Christus,',
        22: 'die is aan Gods rechterhand, heengegaan naaiden hemel, terwijl engelen en krachten en machten Hem onderworpen zijn.',
    },
    4: {
        1: 'Aangezien dan Christus in het vleesch geleden heeft zoo wapent u ook met dezelfde gedachte; want hij die in het vleesch geleden heeft, heeft opgehouden van de zonde,',
        2: 'om nu den tijd dien gij over hebt in het vleesch, niet meer te leven naar de begeerlijkheid der menschen, maar naar den wil van God.',
        3: 'Want het is voldoende in den verloop en tijd den wil der heidenen volbracht te hebben, gewandeld hebbende in ontuchtigheden, begeerlijkheden, wijnzuiperijen, brasserijen, zwelgerijen en gruwelijke afgoderijen,',
        4: 'waarin het hun vreemd voorkomt als gij niet medeloopt tot dezelfde uitgieting van overdadigheid en u daarom lasteren;',
        5: 'die rekenschap zullen geven aan Hem die gereed staat om te oordeelen levenden en dooden.',
        6: 'Want tot dat einde is ook aan de dooden het Evangelie verkondigd, opdat zij wel zouden geoordeeld worden naar den mensch in het vleesch, maar leven zouden naar God in den geest.',
        7: 'Maar het einde van alle dingen is nabij; zijt dan nuchter en waakt tot gebeden;',
        8: 'vooral vurige liefde hebbende jegens elkander, want de liefde bedekt een menigte van zonden;',
        9: 'voor elkander herbergzaam zijnde zonder murmureering.',
        10: 'Een ieder, zooals hij een genadegave ontvangen heeft, bestede die onder u zelven, als goede verzorgers der menigvuldige genade Gods.',
        11: 'Als iemand spreekt, dan spreke hij als woorden Gods, als iemand een bediening heeft, dan diene hij als uit kracht die God verleent, opdat God in alles de glorie ontvange, door Jezus Christus, aan wien de glorie toekomt, en de heerschappij tot in alle eeuwigheid. Amen.',
        12: 'Beminden, laat het u niet vreemd toeschijnen dat gij hevig verdrukt wordt, hetgeen over u komt om u te beproeven, alsof u iets vreemds overkwame;',
        13: 'maar voor zooveel gij deelgenooten van de smarten van Christus zijt zoo moet gij u verblijden, opdat gij u ook verheugen en verblijden moogt in de openbaring zijner glorie.',
        14: 'Als u smaadheid wordt aangedaan om den Naam van Christus, dan zijt gij gelukkig; want de Geest der glorie en van God rust op u.',
        15: 'Doch dat niemand van ulieden lijde als een doodslager, of dief, of kwaaddoener, of die zich met een anders zaken bemoeit.',
        16: 'Maar als iemand lijdt als een christen, dan moet hij zich niet schamen, maar dan moet hij in dien naam God de glorie geven.',
        17: 'Want de tijd is daar dat het oordeel begint van het huis Gods; doch als dit eerst begint van ons, wat zal dan het einde zijn van degenen die aan het Evangelie Gods ongehoorzaam zijn?',
        18: 'En als de rechtvaardige nauwelijks behouden wordt, de goddelooze en de zondaar waar zal die dan verschijnen;',
        19: 'Zoo dan, laat ook hen die lijden naar den wil van God, hun zielen aan den getrouwen Schepper overgeven in weldadigheid.',
    },
    5: {
        1: 'De ouderlingen dan die onder u zijn vermaan ik, de medeouderling en getuige der smarten van Christus, maar die ook deelgenoot ben van de glorie die geopenbaard zal worden:',
        2: 'hoedt de kudde Gods die onder u is en hebt er toezicht over, niet gedwongen maar gewillig, volgens Gods wil, noch om vuil gewin maar uitterharte,',
        3: 'noch als heerschappijvoerders over het erfdeel, maar als voorbeelden zijnde voor de kudde.',
        4: 'En als de overste Herder zal verschenen zijn dan zult gij de onverwelkelijke kroon der glorie verkrijgen.',
        5: 'Zoo ook, gij die jonger zijt, zijt onderdanig aan de oudsten. Ja, gij allen, versiert u zelven met nederigheid, want God wederstaat de hoovaardigen doch aan de nederigen geeft Hij genade.',
        6: 'Vernedert u dan onder de machtige hand Gods, opdat Hij u ter rechter tijd verhooge.',
        7: 'Werpt al uw bekommernis op Hem, want Hij zorgt voor u.',
        8: 'Zijt nuchter, waakt! Uw tegenpartij, de duivel, als een brullende leeuw, gaat hij rond, zoekende wien hij verslinden moge.',
        9: 'Wederstaat hem, vast in het geloof, wetende dat dezelfde smarten geleden worden door uw broeders die in de wereld zijn.',
        10: 'Doch de God van alle genade, die u geroepen heeft tot zijn eeuwige glorie in Christus, nadat gij een weinig zult geleden hebben, die zal u volmaken, versterken, bevestigen en fundeeren.',
        11: 'Hem zij de glorie en de heerschappij tot in alle eeuwigheid! Amen.',
        12: 'Door Silvanus, den getrouwen broeder naar ik meen, heb ik u in het kort geschreven, vermanende en getuigende dat deze is de waarachtige genade Gods; staat daarin vast!',
        13: 'De medeuitverkorenedie in Babylon is groet u, en ook Markus mijn zoon.',
        14: 'Groet elkander met een kus der liefde. Vrede zij met u allen die in Christus zijt!',
    },
}
